def seed_categories_from_parent_work_items(apps, schema_editor):
    """Starts each workspace's product master with the categories already used on parent
    work items (sub work items keep their SKU in the category field, so they're left out)."""
    OrderDetail = apps.get_model("db", "OrderDetail")
    ProductCategory = apps.get_model("db", "ProductCategory")

    rows = (
        OrderDetail._default_manager.filter(
            deleted_at__isnull=True,
            issue__deleted_at__isnull=True,
            issue__parent__isnull=True,
        )
        .exclude(category="")
        .values_list("workspace_id", "category")
        .distinct()
    )
    seen = set()
    to_create = []
    for workspace_id, category in rows:
        name = category.strip()
        key = (workspace_id, name.lower())
        if not name or key in seen:
            continue
        seen.add(key)
        to_create.append(ProductCategory(workspace_id=workspace_id, name=name))
    ProductCategory._default_manager.bulk_create(to_create, batch_size=500)


